namespace ASMILE.BO.Core.FrontOffice.Foundation.Identifiers;

public readonly record struct PropertyId(Guid Value) : IStronglyTypedGuid<PropertyId>
{ public static PropertyId New() => new(Uuid7.NewGuid()); public static PropertyId From(Guid value) => value == Guid.Empty ? throw new ArgumentException("ID cannot be empty.") : new(value); public static bool TryParse(string? value, out PropertyId id) { var ok = Guid.TryParse(value, out var raw) && raw != Guid.Empty; id = ok ? new(raw) : default; return ok; } public override string ToString() => Value.ToString("D"); }
