public readonly record struct IdempotencyKey(string Value)
{ public static IdempotencyKey From(string value) => string.IsNullOrWhiteSpace(value) || value.Length > 160 ? throw new ArgumentException("Idempotency key must contain 1-160 characters.") : new(value.Trim()); public override string ToString() => Value; }
